sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    try {
        var body = request.body.data;

        // Basic validation
        if (!body || !body.short_description) {
            response.setStatus(400);
            return {
                error: "short_description is required"
            };
        }

        // Create Incident
        var inc = new GlideRecord('incident');
        inc.initialize();

        inc.short_description = body.short_description;
        inc.description = body.description || '';
        inc.category = body.category || 'software';
        inc.subcategory = body.subcategory || '';
        inc.impact = body.impact || '3';
        inc.urgency = body.urgency || '3';

        // Custom reported-by fields (since no caller_id)
        if (body.reported_name)
            inc.u_reported_name = body.reported_name;

        if (body.reported_email)
            inc.u_reported_email = body.reported_email;

        // Helpful audit trail
        inc.work_notes = 'Created via IT Support Bot';

        var sysId = inc.insert();

        if (!sysId) {
            response.setStatus(500);
            return {
                error: "Failed to create incident"
            };
        }

        // Success response
        response.setStatus(201);
        return {
            success: true,
            number: inc.number.toString(),
            sys_id: sysId
        };

    } catch (ex) {
        response.setStatus(500);
        return {
            error: ex.message
        };
    }

})(request, response);
